/**
 * Create a hit result object from raycast data.
 *
 * @param {Object} hit - The hit result from raycast
 * @param {THREE.Mesh} mesh - The mesh that was hit
 * @param {number} shooterIndex - Index of the shooter body
 * @param {string} shooterType - Type of shooter ('dynamic' or 'kinematic')
 * @param {Object} [options] - Additional options
 * @param {string} [options.weaponType='hitscan'] - Weapon type for event
 * @param {number} [options.damage=0] - Damage value
 * @returns {Object} Hit result object
 */
export function createHitResult(hit: any, mesh: THREE.Mesh, shooterIndex: number, shooterType: string, options?: {
    weaponType?: string;
    damage?: number;
}): any;
/**
 * Collect all hittable meshes for raycasting.
 *
 * @param {number} shooterIndex - Index of the shooter body
 * @param {string} shooterType - Type of shooter ('dynamic' or 'kinematic')
 * @returns {THREE.Mesh[]} Array of meshes to raycast against
 */
export function collectHittableMeshes(shooterIndex: number, shooterType: string): THREE.Mesh[];
/**
 * Perform a hitscan raycast and return hits.
 *
 * @param {Object} options - Raycast options
 * @param {THREE.Vector3|Object} options.origin - Ray origin
 * @param {THREE.Vector3|Object} options.direction - Ray direction (will be normalized)
 * @param {number} options.shooterIndex - Index of the shooter body
 * @param {string} options.shooterType - Type of shooter ('dynamic' or 'kinematic')
 * @param {number} [options.maxDistance=1000] - Maximum raycast distance
 * @param {boolean} [options.piercing=false] - If true, return all hits along ray
 * @param {string} [options.weaponType='hitscan'] - Weapon type for hit results
 * @param {number} [options.damage=0] - Damage value for hit results
 * @returns {Object[]} Array of hit results
 */
export function performHitscan(options: {
    origin: THREE.Vector3 | any;
    direction: THREE.Vector3 | any;
    shooterIndex: number;
    shooterType: string;
    maxDistance?: number;
    piercing?: boolean;
    weaponType?: string;
    damage?: number;
}): any[];
/**
 * Get camera position and forward direction for camera-based firing.
 *
 * @returns {Object} { origin: THREE.Vector3, direction: THREE.Vector3 }
 */
export function getCameraRay(): any;
